// ═══════════════════════════════════════════════════════════
// FORMAT ERROR — extract useful fields from the error event
// ═══════════════════════════════════════════════════════════
const error = $input.first().json;

const workflowName = error.workflow?.name || 'Unknown Workflow';
const nodeName = error.execution?.lastNodeExecuted || 'Unknown Node';
const errorMessage = error.execution?.error?.message || 'No error message';
const executionId = error.execution?.id || 'N/A';
const timestamp = new Date().toISOString();

// Try to extract input data from the failed node (truncate to prevent overflow)
let inputSummary = 'N/A';
try {
  const data = error.execution?.data;
  if (data) {
    inputSummary = JSON.stringify(data).substring(0, 2000);
  }
} catch (e) {
  inputSummary = 'Could not serialise input data';
}

// Determine severity
let severity = 'WARNING';
if (errorMessage.includes('SPAM_DETECTED')) {
  severity = 'INFO';  // Spam is expected, don't alert
} else if (errorMessage.includes('Validation failed')) {
  severity = 'WARNING';
} else {
  severity = 'ERROR';
}

const emailHtml = `
<div style="font-family:monospace;max-width:640px">
  <h2 style="color:${severity === 'ERROR' ? '#c0392b' : severity === 'WARNING' ? '#e67e22' : '#7f8c8d'}">n8n ${severity}: ${workflowName}</h2>
  <table style="border-collapse:collapse;width:100%">
    <tr><td style="padding:6px;font-weight:bold;border-bottom:1px solid #ddd">Workflow</td><td style="padding:6px;border-bottom:1px solid #ddd">${workflowName}</td></tr>
    <tr><td style="padding:6px;font-weight:bold;border-bottom:1px solid #ddd">Failed Node</td><td style="padding:6px;border-bottom:1px solid #ddd">${nodeName}</td></tr>
    <tr><td style="padding:6px;font-weight:bold;border-bottom:1px solid #ddd">Error</td><td style="padding:6px;border-bottom:1px solid #ddd;color:#c0392b">${errorMessage}</td></tr>
    <tr><td style="padding:6px;font-weight:bold;border-bottom:1px solid #ddd">Execution ID</td><td style="padding:6px;border-bottom:1px solid #ddd">${executionId}</td></tr>
    <tr><td style="padding:6px;font-weight:bold;border-bottom:1px solid #ddd">Timestamp</td><td style="padding:6px;border-bottom:1px solid #ddd">${timestamp}</td></tr>
  </table>
  <details style="margin-top:12px">
    <summary>Input Data (truncated)</summary>
    <pre style="background:#f4f4f4;padding:10px;font-size:11px;overflow:auto;max-height:300px">${inputSummary}</pre>
  </details>
</div>`;

return [{
  json: {
    severity,
    workflowName,
    nodeName,
    errorMessage,
    executionId,
    timestamp,
    inputSummary,
    emailHtml,
    emailSubject: `[n8n ${severity}] ${workflowName} — ${nodeName} failed`,
    shouldAlert: severity === 'ERROR',  // Only email alerts for real errors
    logPayload: {
      severity,
      workflow_name: workflowName,
      node_name: nodeName,
      error_message: errorMessage,
      execution_id: executionId,
    },
  }
}];

